package com.personal.crm;
import android.app.*;import android.content.*;import android.os.Build;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.*;import java.time.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class CrmTest {
 Context context;CrmStore store;
 @Before public void setup(){context=RuntimeEnvironment.getApplication();context.getSharedPreferences("crm",0).edit().clear().commit();store=new CrmStore(context);shadowOf((Application)context).grantPermissions(android.Manifest.permission.POST_NOTIFICATIONS);Reminders.channel(context);}
 JSONObject person(String id)throws Exception{return new JSONObject().put("id",id).put("name","Example Person").put("phone","").put("email","").put("notes","Keep my notes").put("lookupKey","").put("contactId","").put("group","people").put("stage","Interested").put("reminders",true).put("every",1).put("unit","weeks").put("nextAt",System.currentTimeMillis()+3600000).put("lastAt",0);}
 void save(JSONObject p)throws Exception{JSONObject d=store.read();d.getJSONArray("people").put(p);store.write(d);}
 @Test public void emptyInstallHasNoInventedPeople()throws Exception{assertEquals(0,store.read().getJSONArray("people").length());}
 @Test public void dataSurvivesNewStore()throws Exception{save(person("one"));assertEquals("Keep my notes",new CrmStore(context).read().getJSONArray("people").getJSONObject(0).getString("notes"));}
 @Test public void invalidWriteKeepsExistingData()throws Exception{save(person("one"));JSONObject broken=store.read();broken.getJSONArray("people").getJSONObject(0).put("every",0);assertThrows(IllegalArgumentException.class,()->store.write(broken));assertEquals(1,store.read().getJSONArray("people").getJSONObject(0).getInt("every"));}
 @Test public void duplicateIdsRejected()throws Exception{JSONObject d=store.read();d.getJSONArray("people").put(person("one")).put(person("one"));assertThrows(IllegalArgumentException.class,()->store.write(d));}
 @Test public void monthlyCadenceClampsToMonthEnd(){ZoneId zone=ZoneId.of("America/New_York");long start=ZonedDateTime.of(2027,1,31,9,0,0,0,zone).toInstant().toEpochMilli();assertEquals(28,Instant.ofEpochMilli(Reminders.advance(start,1,"months",zone)).atZone(zone).getDayOfMonth());}
 @Test public void weeklyCadenceKeepsLocalTimeAcrossDst(){ZoneId zone=ZoneId.of("America/New_York");long start=ZonedDateTime.of(2027,3,7,9,30,0,0,zone).toInstant().toEpochMilli();ZonedDateTime end=Instant.ofEpochMilli(Reminders.advance(start,1,"weeks",zone)).atZone(zone);assertEquals(9,end.getHour());assertEquals(30,end.getMinute());assertEquals(167,(end.toInstant().toEpochMilli()-start)/3600000);}
 @Test public void schedulingCreatesOneAlarmForEarliestPerson()throws Exception{save(person("one"));save(person("two").put("nextAt",System.currentTimeMillis()+7200000));Reminders.schedule(context);assertEquals(1,shadowOf(context.getSystemService(AlarmManager.class)).getScheduledAlarms().size());}
 @Test public void disablingAllRemindersCancelsAlarm()throws Exception{save(person("one"));Reminders.schedule(context);JSONObject d=store.read();d.getJSONArray("people").getJSONObject(0).put("reminders",false);store.write(d);Reminders.schedule(context);assertTrue(shadowOf(context.getSystemService(AlarmManager.class)).getScheduledAlarms().isEmpty());}
 @Test public void contactedResetsCadenceAndPreservesNotes()throws Exception{save(person("one"));assertTrue(Reminders.contacted(context,"one"));JSONObject p=store.read().getJSONArray("people").getJSONObject(0);assertTrue(p.getLong("lastAt")>0);assertTrue(p.getLong("nextAt")>System.currentTimeMillis());assertEquals("Keep my notes",p.getString("notes"));}
 @Test public void unknownPersonActionDoesNotCreatePerson()throws Exception{assertFalse(Reminders.contacted(context,"missing"));assertEquals(0,store.read().getJSONArray("people").length());}
 @Test public void dueReminderNotifiesOnceThenAdvances()throws Exception{save(person("one").put("nextAt",System.currentTimeMillis()-10000));Reminders.deliver(context);assertEquals(1,shadowOf(context.getSystemService(NotificationManager.class)).getAllNotifications().size());assertTrue(store.read().getJSONArray("people").getJSONObject(0).getLong("nextAt")>System.currentTimeMillis());long revision=store.read().getLong("revision");Reminders.deliver(context);assertEquals(revision,store.read().getLong("revision"));}
 @Test public void removingPersonCancelsTheirSchedule()throws Exception{save(person("one"));Reminders.schedule(context);JSONObject d=store.read();d.put("people",new JSONArray());store.write(d);Reminders.schedule(context);assertTrue(shadowOf(context.getSystemService(AlarmManager.class)).getScheduledAlarms().isEmpty());}
 @Test public void missingContactPermissionKeepsStoredNotes()throws Exception{save(person("one"));Contacts.refresh(context);assertEquals("Keep my notes",store.read().getJSONArray("people").getJSONObject(0).getString("notes"));}
 @Test public void webShellBlocksNetworkAndUntrustedContent(){MainActivity a=Robolectric.buildActivity(MainActivity.class).create().get();assertTrue(a.webForTests().getSettings().getBlockNetworkLoads());assertFalse(a.webForTests().getSettings().getAllowFileAccess());assertFalse(a.webForTests().getSettings().getAllowContentAccess());assertFalse(a.webForTests().getSettings().getDomStorageEnabled());}
 @Test public void staleUiSnapshotCannotOverwriteNewerReminder()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).create().get();String stale=a.bridgeForTests().readState();save(person("one"));assertFalse(a.bridgeForTests().writeState(stale));assertEquals(1,store.read().getJSONArray("people").length());}
 @Test public void corruptStorageDoesNotScheduleOrOverwrite(){context.getSharedPreferences("crm",0).edit().putString("state","not json").commit();Reminders.schedule(context);assertEquals("not json",context.getSharedPreferences("crm",0).getString("state",null));assertTrue(shadowOf(context.getSystemService(AlarmManager.class)).getScheduledAlarms().isEmpty());}
 @Test public void deniedNotificationsKeepScheduleDataButNoAlarm()throws Exception{save(person("one"));shadowOf((Application)context).denyPermissions(android.Manifest.permission.POST_NOTIFICATIONS);Reminders.schedule(context);assertTrue(shadowOf(context.getSystemService(AlarmManager.class)).getScheduledAlarms().isEmpty());assertTrue(store.read().getJSONArray("people").getJSONObject(0).getBoolean("reminders"));}

 @Test public void newCategoriesAndTagsRoundTrip()throws Exception{for(String stage:new String[]{"In progress","Hiatus","DTF"}){JSONObject p=person(stage).put("group","dating").put("stage",stage).put("tags",new JSONArray().put("Snapchat").put("Discord").put("In person"));p.remove("email");save(p);}assertEquals(3,store.read().getJSONArray("people").length());assertEquals("DTF",store.read().getJSONArray("people").getJSONObject(2).getString("stage"));assertEquals(3,store.read().getJSONArray("people").getJSONObject(2).getJSONArray("tags").length());}
 @Test public void legacyCategoriesAndMissingTagsRemainReadable()throws Exception{save(person("legacy").put("stage","Paused"));assertEquals("Keep my notes",new CrmStore(context).read().getJSONArray("people").getJSONObject(0).getString("notes"));}
 @Test public void invalidOrDuplicateTagsCannotOverwriteSavedData()throws Exception{save(person("one"));for(JSONArray tags:new JSONArray[]{new JSONArray().put("Unknown"),new JSONArray().put("Discord").put("Discord")}){JSONObject d=store.read();d.getJSONArray("people").getJSONObject(0).put("tags",tags);assertThrows(IllegalArgumentException.class,()->store.write(d));}assertFalse(store.read().getJSONArray("people").getJSONObject(0).has("tags"));}

 @Test public void interestNextStepsSurviveSaveReloadAndContactUpdates()throws Exception{save(person("interest").put("group","dating").put("nextSteps","Ask about coffee\nArrange Saturday plans"));assertTrue(Reminders.contacted(context,"interest"));JSONObject p=new CrmStore(context).read().getJSONArray("people").getJSONObject(0);assertEquals("Ask about coffee\nArrange Saturday plans",p.getString("nextSteps"));assertEquals("Keep my notes",p.getString("notes"));assertEquals("dating",p.getString("group"));}
 @Test public void invalidNextStepsCannotReplaceSavedData()throws Exception{save(person("interest").put("group","dating").put("nextSteps","Keep this step"));for(Object value:new Object[]{true,42,"x".repeat(4001)}){JSONObject d=store.read();d.getJSONArray("people").getJSONObject(0).put("nextSteps",value);assertThrows(IllegalArgumentException.class,()->store.write(d));}assertEquals("Keep this step",store.read().getJSONArray("people").getJSONObject(0).getString("nextSteps"));}

 @Test public void locationsSurviveReloadAndContactUpdatesForBothGroups()throws Exception{save(person("friend").put("location","School in Portland"));save(person("interest").put("group","dating").put("location","Saturday café event"));assertTrue(Reminders.contacted(context,"friend"));assertTrue(Reminders.contacted(context,"interest"));JSONArray people=new CrmStore(context).read().getJSONArray("people");assertEquals("School in Portland",people.getJSONObject(0).getString("location"));assertEquals("Saturday café event",people.getJSONObject(1).getString("location"));assertEquals("Keep my notes",people.getJSONObject(1).getString("notes"));}
 @Test public void invalidLocationCannotOverwriteStoredProfile()throws Exception{save(person("one").put("location","Keep this location"));for(Object value:new Object[]{false,42,"x".repeat(501)}){JSONObject d=store.read();d.getJSONArray("people").getJSONObject(0).put("location",value);assertThrows(IllegalArgumentException.class,()->store.write(d));}assertEquals("Keep this location",store.read().getJSONArray("people").getJSONObject(0).getString("location"));}

 @Test public void manualOrderSurvivesReloadAndReminderUpdates()throws Exception{save(person("one").put("sortOrder",1));save(person("two").put("sortOrder",0).put("group","dating"));assertTrue(Reminders.contacted(context,"one"));JSONObject d=new CrmStore(context).read();assertEquals(1,d.getJSONArray("people").getJSONObject(0).getInt("sortOrder"));assertEquals(0,d.getJSONArray("people").getJSONObject(1).getInt("sortOrder"));}
 @Test public void invalidManualOrderDoesNotReplaceStoredData()throws Exception{save(person("one"));for(Object order:new Object[]{-1,5000,1.5,"0"}){JSONObject d=store.read();d.getJSONArray("people").getJSONObject(0).put("sortOrder",order);assertThrows(IllegalArgumentException.class,()->store.write(d));}assertFalse(store.read().getJSONArray("people").getJSONObject(0).has("sortOrder"));}
 JSONObject personalNote(String id)throws Exception{return new JSONObject().put("id",id).put("name","Personal example").put("kind","partner").put("notes","Private local notes").put("createdAt",123L);}
 @Test public void personalNotesPersistAndSurviveReminderUpdates()throws Exception{save(person("one"));JSONObject d=store.read();d.put("personalNotes",new JSONArray().put(personalNote("note-one")));store.write(d);assertTrue(Reminders.contacted(context,"one"));JSONObject saved=new CrmStore(context).read().getJSONArray("personalNotes").getJSONObject(0);assertEquals("Private local notes",saved.getString("notes"));assertEquals("partner",saved.getString("kind"));assertEquals(1,store.read().getJSONArray("people").length());}
 @Test public void invalidPersonalNotesDoNotReplaceStoredData()throws Exception{save(person("one"));for(Object invalid:new Object[]{"broken",new JSONArray().put(personalNote("one").put("kind","invalid")),new JSONArray().put(personalNote("one").put("name","")),new JSONArray().put(personalNote("one").put("createdAt",-1)),new JSONArray().put(personalNote("one").put("notes","x".repeat(20001)))}){JSONObject d=store.read();d.put("personalNotes",invalid);assertThrows(IllegalArgumentException.class,()->store.write(d));}assertFalse(store.read().has("personalNotes"));}
 @Test public void duplicatePersonalNoteIdsAreRejected()throws Exception{JSONObject d=store.read();d.put("personalNotes",new JSONArray().put(personalNote("same")).put(personalNote("same")));assertThrows(IllegalArgumentException.class,()->store.write(d));assertEquals(0,store.read().getJSONArray("people").length());}
}
